mapper.insert:
INSERT INTO ip_adjust_log (security_code
                          , security_short_name
                          , security_type
                          , crmw_name
                          , crmw_scode
                          , crmw_mktcode
                          , crmw_stype
                          , adjust_type
                          , adjust_mode
                          , adjust_batch_no
                          , target_pool_id
                          , target_pool_name
                          , pool_type
                          , flow_id
                          , flow_key
                          , flow_type
                          , audit_status
                          , adjuster_id
                          , adjuster_name
                          , adjust_reason
                          , adjust_advice
                          , submit_time
                          , is_deleted
                          , crte_time
                          , updt_time)
VALUES

    (#{row.securityCode}
           , #{row.securityShortName}
           , #{row.securityType}
           , #{row.crmwName}
           , #{row.crmwScode}
           , #{row.crmwMktcode}
           , #{row.crmwStype}
           , #{row.adjustType}
           , #{row.adjustMode}
           , #{row.adjustBatchNo}
           , #{row.targetPoolId}
           , #{row.targetPoolName}
           , #{row.poolType}
           , #{row.flowId}
           , #{row.flowKey}
           , #{row.flowType}
           , #{row.auditStatus}
           , #{row.adjusterId}
           , #{row.adjusterName}
           , #{row.adjustReason}
           , #{row.adjustAdvice}
           , COALESCE(#{row.submitTime}, NOW())
           , 0
           , NOW()
           , NOW())

INSERT INTO ip_adjust_step (adjust_log_id
                           , adjust_batch_no
                           , flow_node_id
                           , node_code
                           , node_label
                           , node_type
                           , approval_strategy
                           , sort_order
                           , step_status
                           , handler_id
                           , handler_name
                           , process_action
                           , process_comment
                           , start_time
                           , process_time
                           , crte_time
                           , updt_time)
VALUES

    (#{row.adjustLogId}
           , #{row.adjustBatchNo}
           , #{row.flowNodeId}
           , #{row.nodeCode}
           , #{row.nodeLabel}
           , #{row.nodeType}
           , #{row.approvalStrategy}
           , #{row.sortOrder}
           , #{row.stepStatus}
           , #{row.handlerId}
           , #{row.handlerName}
           , #{row.processAction}
           , #{row.processComment}
           , #{row.startTime}
           , #{row.processTime}
           , NOW()
           , NOW())

INSERT INTO ip_pool_status (security_code
                          , security_short_name
                          , security_type
                          , crmw_name
                          , crmw_scode
                          , crmw_mktcode
                          , crmw_stype
                          , adjust_type
                          , adjust_mode
                          , adjust_batch_no
                          , adjust_log_id
                          , target_pool_id
                          , target_pool_name
                          , pool_type
                          , flow_id
                          , flow_key
                          , flow_type
                          , audit_status
                          , adjuster_id
                          , adjuster_name
                          , adjust_reason
                          , adjust_advice
                          , submit_time
                          , entry_time
                          , is_deleted
                          , crte_time
                          , updt_time)
VALUES

    (#{row.securityCode}
           , #{row.securityShortName}
           , #{row.securityType}
           , #{row.crmwName}
           , #{row.crmwScode}
           , #{row.crmwMktcode}
           , #{row.crmwStype}
           , #{row.adjustType}
           , #{row.adjustMode}
           , #{row.adjustBatchNo}
           , #{row.adjustLogId}
           , #{row.targetPoolId}
           , #{row.targetPoolName}
           , #{row.poolType}
           , #{row.flowId}
           , #{row.flowKey}
           , #{row.flowType}
           , #{row.auditStatus}
           , #{row.adjusterId}
           , #{row.adjusterName}
           , #{row.adjustReason}
           , #{row.adjustAdvice}
           , NOW()
           , NOW()
           , 0
           , NOW()
           , NOW())
